import { useState } from "react";
import Button from "../common/Button/Button";
import styles from "./AuthCard.module.scss";
import TextInput from "../common/Inputs/TextInput/TextInput";
import TextButton from "../common/TextButton/TextButton";

type AuthType = "login" | "signup";

interface FormData {
  fullName?: string;
  email: string;
  password: string;
  confirmPassword?: string;
}

interface FormErrors {
  fullName?: string;
  email?: string;
  password?: string;
  confirmPassword?: string;
}

const AuthCard = () => {
  const [authType, setAuthType] = useState<AuthType>("login");
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState<FormData>({
    fullName: "",
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [errors, setErrors] = useState<FormErrors>({});

  const handleInputChange = (field: keyof FormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: "" }));
    }
  };

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};

    // Email validation
    if (!formData.email) {
      newErrors.email = "Email is required";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = "Please enter a valid email";
    }

    // Password validation
    if (!formData.password) {
      newErrors.password = "Password is required";
    } else if (formData.password.length < 6) {
      newErrors.password = "Password must be at least 6 characters";
    }

    // Signup specific validations
    if (authType === "signup") {
      if (!formData.fullName?.trim()) {
        newErrors.fullName = "Full name is required";
      }

      if (!formData.confirmPassword) {
        newErrors.confirmPassword = "Please confirm your password";
      } else if (formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = "Passwords do not match";
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsLoading(true);

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 2000));

      if (authType === "login") {
        console.log("Login:", { email: formData.email, password: formData.password });
      } else {
        console.log("Signup:", formData);
      }

      // Handle success (redirect, show message, etc.)
    } catch (error) {
      console.error("Auth error:", error);
      // Handle error
    } finally {
      setIsLoading(false);
    }
  };

  const switchAuthType = (type: AuthType) => {
    setAuthType(type);
    setErrors({});
    setFormData({
      fullName: "",
      email: "",
      password: "",
      confirmPassword: "",
    });
  };

  return (
    <div className={styles.authContainer}>
      {/* Header with Title */}
      <div className={styles.authHeader}>
        <h1 className={styles.authTitle}>
          {authType === "login" ? "Welcome Back" : "Create Account"}
        </h1>
        <p className={styles.authSubtitle}>
          {authType === "login" 
            ? "Sign in to continue to your account" 
            : "Sign up to get started with us"}
        </p>
      </div>

      {/* Auth Type Switch */}
      <div className={styles.authSwitchButtonBox}>
        <button
          type="button"
          className={`${styles.switchBtn} ${
            authType === "login" ? styles.activeBtn : ""
          }`}
          onClick={() => switchAuthType("login")}
        >
          Login
        </button>
        <button
          type="button"
          className={`${styles.switchBtn} ${
            authType === "signup" ? styles.activeBtn : ""
          }`}
          onClick={() => switchAuthType("signup")}
        >
          Sign Up
        </button>
        <div 
          className={styles.slidingIndicator}
          style={{ transform: authType === "signup" ? "translateX(100%)" : "translateX(0)" }}
        />
      </div>

      {/* Form */}
      <form onSubmit={handleSubmit} className={styles.authForm}>
        <div className={styles.inputsContainer}>
          {authType === "signup" && (
            <TextInput
              label="Full Name"
              type="text"
              placeholder="John Doe"
              value={formData.fullName}
              onChange={(e) => handleInputChange("fullName", e.target.value)}
              errorMessage={errors.fullName}
            />
          )}

          <TextInput
            label="Email Address"
            type="email"
            placeholder="you@example.com"
            value={formData.email}
            onChange={(e) => handleInputChange("email", e.target.value)}
            errorMessage={errors.email}
          />

          <TextInput
            label="Password"
            type="password"
            placeholder="Enter your password"
            value={formData.password}
            onChange={(e) => handleInputChange("password", e.target.value)}
            errorMessage={errors.password}
          />

          {authType === "signup" && (
            <TextInput
              label="Confirm Password"
              type="password"
              placeholder="Confirm your password"
              value={formData.confirmPassword}
              onChange={(e) => handleInputChange("confirmPassword", e.target.value)}
              errorMessage={errors.confirmPassword}
            />
          )}
        </div>

        {/* Forgot Password Link (Login only) */}
        {authType === "login" && (
          <div className={styles.forgotPasswordContainer}>
            <TextButton
              href="/forgot-password"
              variant="primary"
              size="sm"
            >
              Forgot Password?
            </TextButton>
          </div>
        )}

        {/* Submit Button */}
        <Button
          className={styles.submitBtn}
          text={isLoading ? "Please wait..." : authType === "login" ? "Sign In" : "Create Account"}
          onClick={()=>handleSubmit}
        />
      </form>

      {/* Footer */}
      <div className={styles.authFooter}>
        <p className={styles.footerText}>
          {authType === "login" ? "Don't have an account?" : "Already have an account?"}{" "}
          <TextButton
            onClick={() => switchAuthType(authType === "login" ? "signup" : "login")}
            variant="primary"
            size="sm"
          >
            {authType === "login" ? "Sign up" : "Login"}
          </TextButton>
        </p>
      </div>
    </div>
  );
};

export default AuthCard;
